import 'dart:convert';
import 'dart:io';
import 'package:cryptography/cryptography.dart';
import 'package:http/http.dart' as http;
class ContentPackageRef { const ContentPackageRef({required this.file, required this.sha256}); final String file, sha256; factory ContentPackageRef.fromJson(Map<String,dynamic> j)=>ContentPackageRef(file:j['file'] as String,sha256:j['sha256'] as String); }
class ContentManifest { const ContentManifest({required this.contentVersion,required this.schemaVersion,required this.packages}); final String contentVersion; final int schemaVersion; final List<ContentPackageRef> packages; factory ContentManifest.fromJson(Map<String,dynamic> j)=>ContentManifest(contentVersion:j['content_version'] as String,schemaVersion:j['schema_version'] as int,packages:(j['packages'] as List).map((x)=>ContentPackageRef.fromJson(x as Map<String,dynamic>)).toList()); }
class ContentUpdateService { ContentUpdateService(this.client); final http.Client client; Future<ContentManifest> fetchManifest(Uri uri) async { final r=await client.get(uri); if(r.statusCode!=200) throw HttpException('Manifest ${r.statusCode}'); return ContentManifest.fromJson(jsonDecode(r.body) as Map<String,dynamic>); } Future<List<int>> verifiedPackage(Uri baseUri,ContentPackageRef p) async { final r=await client.get(baseUri.resolve(p.file)); if(r.statusCode!=200) throw HttpException('Package ${r.statusCode}'); final digest=await Sha256().hash(r.bodyBytes); final actual=digest.bytes.map((b)=>b.toRadixString(16).padLeft(2,'0')).join(); if(actual.toLowerCase()!=p.sha256.toLowerCase()) throw const FormatException('SHA-256 mismatch'); return r.bodyBytes; } }